PhantomUI_SpellLocale = PhantomUI_SpellLocale or {}
for lang, map in pairs(ADD) do
	local t = PhantomUI_SpellLocale[lang]
	if not t then
		t = {}
		PhantomUI_SpellLocale[lang] = t
	end
	for en, name in pairs(map) do
		if t[en] == nil then
			t[en] = name
		end
	end
end

